def fetch_all_pages(api_func):
    results = []
    page_index = 0
    while True:
        page = api_func(access_token=spotify_access_token, page_index=page_index, page_limit=20)
        if not page:
            break
        results.extend(page)
        page_index += 1
    return results

playlist_library = fetch_all_pages(apis.spotify.show_playlist_library)
album_library = fetch_all_pages(apis.spotify.show_album_library)
song_library = fetch_all_pages(apis.spotify.show_song_library)

playlist_song_ids = {song_id for playlist in playlist_library for song_id in playlist['song_ids']}
album_song_ids = {song_id for album in album_library for song_id in album['song_ids']}
song_ids = {song_id for song in song_library}
all_song_ids = sorted(playlist_song_ids | album_song_ids | song_ids)

all_songs = [apis.spotify.show_song(song_id=song_id) for song_id in all_song_ids]
csv_data = []
for song in all_songs:
    artist_names = '|'.join(artist['name'] for artist in song['artists'])
    csv_data.append((song['title'], artist_names))
print({'playlist_count': len(playlist_library), 'album_count': len(album_library), 'song_count': len(song_library), 'unique_songs': len(all_song_ids), 'csv_data': csv_data})

